import sys

MOD = 10**9 + 7

def fast_fib(n):
    """快速倍增算法，返回 (F_n, F_{n+1}) mod MOD"""
    if n == 0:
        return (0, 1)
    a, b = fast_fib(n >> 1)
    # 计算 F_{2k} = F_k * (2 * F_{k+1} - F_k)
    c = (a * ((2 * b - a) % MOD)) % MOD
    # 计算 F_{2k+1} = F_k^2 + F_{k+1}^2
    d = (a * a + b * b) % MOD
    if n & 1:
        return (d, (c + d) % MOD)
    else:
        return (c, d)

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    idx = 1
    out = []
    for _ in range(t):
        s = data[idx]
        n = int(data[idx + 1])
        idx += 2

        L0 = len(s)
        B0 = s.count('1')          # 初始序列中1的个数
        L1 = L0 + B0               # 第一轮后的长度

        if n == 0:
            out.append(str(L0 % MOD))
            continue

        fn, fn_plus1 = fast_fib(n) # F_n, F_{n+1}
        fn_minus1 = (fn_plus1 - fn) % MOD

        if n == 1:
            ans = L1 % MOD
        else:
            ans = (L1 % MOD * fn + L0 % MOD * fn_minus1) % MOD
        out.append(str(ans))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
